/**
 * OSRS achievement diaries.
 *
 * IDs are `${area}|${tier}` (e.g. "Varrock|easy").
 * Data is generated by scripts/fetch-diary-tasks.ts — re-run to update.
 */

import diaryDataJson from './diary-data.json';
import type { SkillReq } from './quest-db';

export type DiaryTier = 'easy' | 'medium' | 'hard' | 'elite';

export const DIARY_TIERS: DiaryTier[] = ['easy', 'medium', 'hard', 'elite'];

export interface DiaryTask {
  text: string;
  skillReqs: SkillReq[];
  questReqs: string[];
}

export interface DiaryEntry {
  id: string;
  area: string;
  tier: DiaryTier;
  name: string;
  tasks: DiaryTask[];
  skillReqs: SkillReq[];
  questReqs: string[];
}

export const DIARY_DATABASE = diaryDataJson as Record<string, DiaryEntry>;

export function getDiary(diaryId: string): DiaryEntry | undefined {
  return DIARY_DATABASE[diaryId];
}

export function getDiaryName(diaryId: string): string {
  return DIARY_DATABASE[diaryId]?.name ?? diaryId;
}

export function previousDiaryId(diaryId: string): string | undefined {
  const entry = DIARY_DATABASE[diaryId];
  if (!entry) return undefined;
  const index = DIARY_TIERS.indexOf(entry.tier);
  if (index <= 0) return undefined;
  const previous = `${entry.area}|${DIARY_TIERS[index - 1]}`;
  return DIARY_DATABASE[previous] ? previous : undefined;
}

const tierRank = (tier: DiaryTier) => DIARY_TIERS.indexOf(tier);

export const ALL_DIARIES = Object.values(DIARY_DATABASE).sort(
  (a, b) => a.area.localeCompare(b.area) || tierRank(a.tier) - tierRank(b.tier),
);

export const DIARY_AREAS = [...new Set(ALL_DIARIES.map((diary) => diary.area))];

/** Flip one task and return a completed array the same length as the diary. */
export function withToggledTask(completed: boolean[], taskCount: number, index: number): boolean[] {
  const next = Array.from({ length: taskCount }, (_, i) => completed[i] ?? false);
  if (index >= 0 && index < taskCount) next[index] = !next[index];
  return next;
}

export function diaryCheckedCount(completed: boolean[], taskCount: number): number {
  let count = 0;
  for (let i = 0; i < taskCount; i++) {
    if (completed[i]) count++;
  }
  return count;
}
